VOUCHER_APPROVAL_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Busy Voucher Approval</title>\n    <!-- Tailwind CSS -->\n    <script src="https://cdn.tailwindcss.com"></script>\n    <!-- SweetAlert2 for beautiful popups -->\n    <script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>\n    <!-- FontAwesome for icons -->\n    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">\n    <!-- Google Fonts -->\n    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">\n    <style>\n        body {\n            font-family: \'Inter\', sans-serif;\n            background-color: #0f172a; /* Tailwind slate-900 */\n            color: #f8fafc;\n            overflow: hidden; /* We\'ll handle scrolling internally */\n        }\n        \n        .glass-card {\n            background: rgba(30, 41, 59, 0.7);\n            backdrop-filter: blur(10px);\n            -webkit-backdrop-filter: blur(10px);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n            transition: transform 0.2s ease, box-shadow 0.2s ease;\n        }\n        \n        .glass-card:hover {\n            transform: translateY(-1px);\n            box-shadow: 0 4px 15px -3px rgba(0, 0, 0, 0.5);\n        }\n\n        .scrollable {\n            overflow-y: auto;\n            overflow-x: hidden;\n            scrollbar-width: thin;\n            scrollbar-color: #475569 transparent;\n        }\n        .scrollable::-webkit-scrollbar {\n            width: 4px;\n        }\n        .scrollable::-webkit-scrollbar-thumb {\n            background-color: #475569;\n            border-radius: 10px;\n        }\n        \n        .btn-modern {\n            position: relative;\n            overflow: hidden;\n            transition: all 0.2s ease;\n        }\n        \n        .btn-modern:active {\n            transform: scale(0.95);\n        }\n\n        /* Loading Skeleton */\n        .skeleton {\n            background: linear-gradient(90deg, #1e293b 25%, #334155 50%, #1e293b 75%);\n            background-size: 200% 100%;\n            animation: skeleton-loading 1.5s infinite;\n        }\n        @keyframes skeleton-loading {\n            0% { background-position: 200% 0; }\n            100% { background-position: -200% 0; }\n        }\n    </style>\n</head>\n<body class="h-screen flex flex-col items-center bg-slate-950 text-sm overflow-hidden select-none">\n    <div class="w-full max-w-xl h-full flex flex-col bg-slate-900 shadow-2xl border-x border-slate-800/80">\n\n        <!-- Top Navigation Bar -->\n        <nav class="glass-card flex justify-between items-center px-3 py-2 z-10 sticky top-0 border-b border-slate-700">\n            <div class="flex items-center gap-2">\n                <div id="status-indicator" class="w-2.5 h-2.5 rounded-full bg-yellow-500 animate-pulse"></div>\n                <h1 class="text-base font-bold tracking-tight text-white" id="status-text">BFE Connecting...</h1>\n                {% if is_client %}\n                <span class="bg-indigo-500/20 text-indigo-300 text-[10px] font-semibold px-2 py-0.5 rounded border border-indigo-500/30">Client View</span>\n                {% endif %}\n            </div>\n            <div class="flex gap-2">\n                <button id="lock-btn" onclick="toggleLock()" class="btn-modern px-3 py-1.5 rounded bg-red-500 hover:bg-red-600 font-medium text-white shadow-lg flex items-center gap-1 text-xs">\n                    <i class="fa-solid fa-lock"></i> <span>Locked</span>\n                </button>\n                <button id="refresh-btn" onclick="refreshData()" class="btn-modern px-3 py-1.5 rounded bg-indigo-500 hover:bg-indigo-600 font-medium text-white shadow-lg disabled:opacity-50 text-xs">\n                    <i class="fa-solid fa-arrows-rotate"></i>\n                </button>\n            </div>\n        </nav>\n\n        <!-- Tabs and Bulk Actions -->\n        <div class="px-3 mb-2 flex justify-between items-end">\n            <div class="flex space-x-1 p-1 bg-slate-800 rounded-lg" role="tablist">\n                <button id="tab-pending" onclick="switchTab(\'pending\')" class="px-3 py-1.5 text-xs font-semibold rounded bg-slate-700 text-white shadow transition-all duration-200">\n                    <i class="fa-solid fa-xmark text-red-400 mr-1"></i> Pending\n                    <span id="pending-badge" class="ml-1 bg-red-500 text-white px-1.5 rounded-full text-[10px]">0</span>\n                </button>\n                <button id="tab-approved" onclick="switchTab(\'approved\')" class="px-3 py-1.5 text-xs font-medium rounded text-slate-400 hover:text-white transition-all duration-200">\n                    <i class="fa-solid fa-check text-emerald-400 mr-1"></i> Apprvd\n                </button>\n            </div>\n            \n            <!-- Action Buttons -->\n            <div id="action-pending" class="block">\n                <button onclick="approveAll()" id="btn-approve-all" disabled class="btn-modern px-3 py-1.5 rounded bg-emerald-500 hover:bg-emerald-600 disabled:bg-slate-700 disabled:text-slate-400 font-bold text-white shadow-lg text-xs transition-all duration-200">\n                    <i class="fa-solid fa-check-double mr-1"></i> Apprv All\n                </button>\n            </div>\n            <div id="action-approved" class="hidden">\n                <button onclick="cancelApproval()" id="btn-cancel" disabled class="btn-modern px-3 py-1.5 rounded bg-red-500 hover:bg-red-600 disabled:bg-slate-700 disabled:text-slate-400 font-bold text-white shadow-lg text-xs transition-all duration-200">\n                    <i class="fa-solid fa-ban mr-1"></i> Cancel\n                </button>\n            </div>\n        </div>\n\n        <!-- Content Area -->\n        <div class="flex-1 px-2 pb-2 overflow-hidden flex flex-col">\n            <!-- Pending View -->\n            <div id="view-pending" class="scrollable flex-1 pr-1 pb-4">\n                <div id="pending-container" class="space-y-2 pt-1">\n                    <!-- Skeletons (Initial load) -->\n                    <div class="glass-card rounded p-3 w-full h-20 skeleton"></div>\n                    <div class="glass-card rounded p-3 w-full h-20 skeleton"></div>\n                </div>\n            </div>\n\n            <!-- Approved View (Compact Cards instead of wide Table) -->\n            <div id="view-approved" class="hidden flex-1 scrollable pr-1 pb-4">\n                <!-- Select All Checkbox for Approved -->\n                <div class="flex items-center gap-2 mb-2 px-2 py-1 bg-slate-800/50 rounded border border-slate-700/50">\n                    <input type="checkbox" id="selectAll" onclick="toggleSelectAll()" class="rounded bg-slate-700 border-slate-600 w-3 h-3 text-indigo-500 focus:ring-0">\n                    <label for="selectAll" class="text-xs text-slate-400 font-medium cursor-pointer">Select All Approved</label>\n                </div>\n                \n                <div id="approved-container" class="space-y-2">\n                    <!-- Approved rows go here -->\n                </div>\n                <div id="approved-empty" class="hidden flex-col items-center justify-center h-48 text-slate-500">\n                    <i class="fa-solid fa-folder-open text-3xl mb-2"></i>\n                    <p class="text-xs">No approved vouchers</p>\n                </div>\n            </div>\n        </div>\n        \n        <!-- Footer Status -->\n        <div class="px-3 py-1.5 text-[10px] text-slate-400 flex justify-between items-center bg-slate-950 border-t border-slate-800">\n            <span id="last-updated">Last updated: Never</span>\n            <span class="text-indigo-400 font-medium cursor-pointer hover:text-indigo-300 transition-colors" onclick="copyClientLink()" title="Click to copy link for client computers">\n                <i class="fa-solid fa-desktop mr-1"></i>Client PC: <b id="client-ip-display" class="text-white select-all">{{ client_url if client_url else \'http://192.168.1.6:5042\' }}</b>\n            </span>\n        </div>\n    </div>\n\n    <script>\n        let isLocked = true;\n        let isBfeConnected = false;\n        let pendingData = [];\n        let approvedData = [];\n        let selectedApproved = new Set();\n        let refreshInterval = null;\n\n        // Startup\n        document.addEventListener(\'DOMContentLoaded\', () => {\n            checkStatus();\n            refreshInterval = setInterval(checkStatus, 15000);\n        });\n\n        function switchTab(tab) {\n            const btnP = document.getElementById(\'tab-pending\');\n            const btnA = document.getElementById(\'tab-approved\');\n            const vP = document.getElementById(\'view-pending\');\n            const vA = document.getElementById(\'view-approved\');\n            const aP = document.getElementById(\'action-pending\');\n            const aA = document.getElementById(\'action-approved\');\n\n            if(tab === \'pending\') {\n                btnP.className = "px-3 py-1.5 text-xs font-semibold rounded bg-slate-700 text-white shadow transition-all duration-200";\n                btnA.className = "px-3 py-1.5 text-xs font-medium rounded text-slate-400 hover:text-white transition-all duration-200";\n                vP.classList.remove(\'hidden\');\n                vA.classList.add(\'hidden\');\n                aP.classList.remove(\'hidden\');\n                aA.classList.add(\'hidden\');\n            } else {\n                btnA.className = "px-3 py-1.5 text-xs font-semibold rounded bg-slate-700 text-white shadow transition-all duration-200";\n                btnP.className = "px-3 py-1.5 text-xs font-medium rounded text-slate-400 hover:text-white transition-all duration-200";\n                vA.classList.remove(\'hidden\');\n                vP.classList.add(\'hidden\');\n                aA.classList.remove(\'hidden\');\n                aP.classList.add(\'hidden\');\n            }\n        }\n\n        function toggleLock() {\n            if(isLocked) {\n                Swal.fire({\n                    title: \'Unlock Application\',\n                    input: \'password\',\n                    inputPlaceholder: \'Password\',\n                    background: \'#1e293b\',\n                    color: \'#fff\',\n                    confirmButtonColor: \'#6366f1\',\n                    showCancelButton: true,\n                    cancelButtonColor: \'#475569\',\n                    customClass: { popup: \'text-sm\' }\n                }).then((result) => {\n                    if(result.isConfirmed) {\n                        if(result.value === \'1970\') {\n                            isLocked = false;\n                            updateLockUI();\n                        } else {\n                            Swal.fire({\n                                icon: \'error\',\n                                title: \'Incorrect Password\',\n                                background: \'#1e293b\',\n                                color: \'#fff\',\n                                confirmButtonColor: \'#6366f1\'\n                            });\n                        }\n                    }\n                });\n            } else {\n                isLocked = true;\n                updateLockUI();\n            }\n        }\n\n        function updateLockUI() {\n            const btn = document.getElementById(\'lock-btn\');\n            if(isLocked) {\n                btn.className = "btn-modern px-3 py-1.5 rounded bg-red-500 hover:bg-red-600 font-medium text-white shadow-lg flex items-center gap-1 text-xs";\n                btn.innerHTML = \'<i class="fa-solid fa-lock"></i> <span>Locked</span>\';\n            } else {\n                btn.className = "btn-modern px-3 py-1.5 rounded bg-emerald-500 hover:bg-emerald-600 font-medium text-white shadow-lg flex items-center gap-1 text-xs";\n                btn.innerHTML = \'<i class="fa-solid fa-lock-open"></i> <span>Unlock</span>\';\n            }\n            updateActionButtons();\n        }\n\n        function updateActionButtons() {\n            document.getElementById(\'btn-approve-all\').disabled = isLocked || pendingData.length === 0;\n            document.getElementById(\'btn-cancel\').disabled = isLocked || selectedApproved.size === 0;\n        }\n\n        function formatInr(num) {\n            return num.toLocaleString(\'en-IN\', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n        }\n\n        function getColorForCreator(creator) {\n            const c = creator.toUpperCase();\n            if(c === \'ADMIN\') return \'text-rose-400\';\n            if(c === \'SHREYAS\') return \'text-sky-400\';\n            if(c === \'GOPAL\') return \'text-purple-400\';\n            return \'text-slate-300\';\n        }\n\n        async function checkStatus() {\n            try {\n                const res = await fetch(\'/api/status\');\n                const data = await res.json();\n                isBfeConnected = data.bfe_active;\n                \n                const indicator = document.getElementById(\'status-indicator\');\n                const text = document.getElementById(\'status-text\');\n                \n                if(isBfeConnected) {\n                    indicator.className = "w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-[0_0_6px_rgba(16,185,129,0.8)]";\n                    text.innerText = "Connected to Busy";\n                    text.className = "text-base font-bold tracking-tight text-emerald-400";\n                    document.getElementById(\'refresh-btn\').disabled = false;\n                    fetchData();\n                } else {\n                    indicator.className = "w-2.5 h-2.5 rounded-full bg-red-500 animate-pulse shadow-[0_0_6px_rgba(239,68,68,0.8)]";\n                    text.innerText = "BFE Disconnected";\n                    text.className = "text-base font-bold tracking-tight text-red-400";\n                    document.getElementById(\'refresh-btn\').disabled = true;\n                }\n            } catch(e) {\n                console.error(e);\n            }\n        }\n\n        async function refreshData() {\n            const btn = document.getElementById(\'refresh-btn\');\n            btn.innerHTML = \'<i class="fa-solid fa-circle-notch fa-spin"></i>\';\n            btn.disabled = true;\n            await fetchData();\n            btn.innerHTML = \'<i class="fa-solid fa-arrows-rotate"></i>\';\n            btn.disabled = false;\n        }\n\n        async function fetchData() {\n            try {\n                const res = await fetch(\'/api/data\');\n                const data = await res.json();\n                \n                if(data.success) {\n                    pendingData = data.unapproved;\n                    approvedData = data.approved;\n                    document.getElementById(\'last-updated\').innerText = `Updated: ${new Date().toLocaleTimeString([], {hour: \'2-digit\', minute:\'2-digit\'})}`;\n                    renderPending();\n                    renderApproved();\n                    updateActionButtons();\n                } else {\n                    throw new Error(data.error);\n                }\n            } catch(e) {\n                console.error("Fetch error:", e);\n                const text = document.getElementById(\'status-text\');\n                const indicator = document.getElementById(\'status-indicator\');\n                indicator.className = "w-2.5 h-2.5 rounded-full bg-red-500 animate-pulse";\n                text.innerText = "Fetch Error (BFE)";\n                text.className = "text-base font-bold tracking-tight text-red-400";\n            }\n        }\n\n        function renderPending() {\n            const container = document.getElementById(\'pending-container\');\n            document.getElementById(\'pending-badge\').innerText = pendingData.length;\n            \n            if(pendingData.length === 0) {\n                container.innerHTML = `\n                <div class="flex flex-col items-center justify-center h-48 text-slate-500">\n                    <i class="fa-solid fa-glass-cheers text-4xl mb-3 text-emerald-500/50"></i>\n                    <p class="text-sm font-medium">All caught up!</p>\n                </div>`;\n                return;\n            }\n\n            container.innerHTML = \'\';\n            pendingData.forEach((item, index) => {\n                const isChanged = item[8] === "Amount Changed";\n                const bgClass = isChanged ? \'bg-rose-900/20 border-rose-500/50\' : \'bg-slate-800/60 border-slate-700/50\';\n                \n                const card = document.createElement(\'div\');\n                card.className = `glass-card p-2.5 rounded border flex justify-between items-center ${bgClass} mb-2 fade-in`;\n                card.style.animationDelay = `${index * 0.03}s`;\n                \n                let countBadge = item[7] > 0 ? `<span class="bg-amber-500/20 text-amber-400 text-[10px] px-1 rounded font-bold ml-1 flex items-center gap-0.5"><i class="fa-solid fa-rotate text-[8px]"></i> ${item[7]}</span>` : \'\';\n                let prevInfo = item[5] !== "-" ? `<span class="text-[10px] text-rose-400 font-medium ml-1 flex-shrink-0">(Was ₹${formatInr(item[5])})</span>` : \'\';\n                let changeWarn = isChanged ? `<span class="text-[10px] bg-rose-500/20 text-rose-400 px-1 rounded ml-1 font-bold flex-shrink-0"><i class="fa-solid fa-triangle-exclamation"></i> Changed</span>` : \'\';\n\n                card.innerHTML = `\n                    <div class="flex-1 min-w-0 pr-2">\n                        <div class="flex items-center gap-1.5 mb-0.5 flex-wrap">\n                            <span class="text-slate-400 font-bold text-[11px] bg-slate-900/50 px-1 rounded"><i class="fa-solid fa-receipt mr-0.5"></i>${item[1]}</span>\n                            <span class="text-slate-500 text-[10px]">${item[2]}</span>\n                            <span class="text-[10px] font-bold ${getColorForCreator(item[4])}">${item[4]}</span>\n                            ${countBadge}\n                        </div>\n                        <h3 class="text-xs font-bold text-white mb-0.5 truncate" title="${item[3]}">${item[3]}</h3>\n                        <div class="flex items-center flex-wrap">\n                            <span class="text-sm font-bold text-emerald-400">₹${formatInr(item[6])}</span>\n                            ${prevInfo}\n                            ${changeWarn}\n                        </div>\n                    </div>\n                    <div class="pl-2 border-l border-slate-700/50 flex-shrink-0">\n                        <button onclick=\'approveSingle(${JSON.stringify(item)})\' class="group relative overflow-hidden rounded w-10 h-10 bg-emerald-500/10 border border-emerald-500/30 hover:bg-emerald-500 transition-all duration-200 flex items-center justify-center shadow">\n                            <i class="fa-solid fa-check text-lg text-emerald-400 group-hover:text-white group-hover:scale-110 transition-transform"></i>\n                        </button>\n                    </div>\n                `;\n                container.appendChild(card);\n            });\n        }\n\n        function renderApproved() {\n            const container = document.getElementById(\'approved-container\');\n            const empty = document.getElementById(\'approved-empty\');\n            \n            container.innerHTML = \'\';\n            \n            if(approvedData.length === 0) {\n                empty.classList.remove(\'hidden\');\n                empty.classList.add(\'flex\');\n                return;\n            }\n            \n            empty.classList.add(\'hidden\');\n            empty.classList.remove(\'flex\');\n            \n            // Clean up selected Set\n            const currentIds = new Set(approvedData.map(a => a[0]));\n            for (let id of selectedApproved) {\n                if (!currentIds.has(id)) selectedApproved.delete(id);\n            }\n\n            approvedData.forEach(item => {\n                const isChecked = selectedApproved.has(item[0]) ? "checked" : "";\n                \n                const card = document.createElement(\'div\');\n                card.className = "glass-card p-2 rounded border border-slate-700/50 bg-slate-800/40 hover:bg-slate-800/80 cursor-pointer flex items-center gap-2 mb-1.5 transition-colors";\n                \n                card.onclick = (e) => {\n                    if(e.target.tagName !== \'INPUT\') {\n                        const cb = document.getElementById(`cb-${item[0]}`);\n                        cb.checked = !cb.checked;\n                        toggleRowSelect(item[0], cb.checked);\n                    }\n                };\n\n                card.innerHTML = `\n                    <div class="flex-shrink-0 pt-0.5">\n                        <input type="checkbox" id="cb-${item[0]}" onchange="toggleRowSelect(${item[0]}, this.checked)" ${isChecked} class="rounded bg-slate-700 border-slate-600 w-3.5 h-3.5 text-indigo-500 focus:ring-0">\n                    </div>\n                    <div class="flex-1 min-w-0">\n                        <div class="flex justify-between items-center mb-0.5">\n                            <span class="text-[11px] text-slate-300 font-medium truncate w-1/2">${item[1]} • <span class="${getColorForCreator(item[4])}">${item[4]}</span></span>\n                            <span class="text-[10px] text-slate-500 text-right">${item[2]}</span>\n                        </div>\n                        <div class="flex justify-between items-end">\n                            <h3 class="text-xs font-semibold text-slate-200 truncate w-3/5" title="${item[3]}">${item[3]}</h3>\n                            <span class="text-sm font-bold text-emerald-500/80">₹${formatInr(item[6])}</span>\n                        </div>\n                    </div>\n                `;\n                container.appendChild(card);\n            });\n            updateActionButtons();\n        }\n\n        function toggleRowSelect(id, isSelected) {\n            if(isSelected) selectedApproved.add(id);\n            else selectedApproved.delete(id);\n            \n            const selectAll = document.getElementById(\'selectAll\');\n            selectAll.checked = (selectedApproved.size > 0 && selectedApproved.size === approvedData.length);\n            \n            updateActionButtons();\n        }\n\n        function toggleSelectAll() {\n            const selectAll = document.getElementById(\'selectAll\').checked;\n            approvedData.forEach(item => {\n                const cb = document.getElementById(`cb-${item[0]}`);\n                if(cb) cb.checked = selectAll;\n                if(selectAll) selectedApproved.add(item[0]);\n                else selectedApproved.clear();\n            });\n            updateActionButtons();\n        }\n\n        function approveSingle(item) {\n            if(isLocked) {\n                Swal.fire({icon: \'warning\', title: \'Locked!\', background: \'#1e293b\', color: \'#fff\', confirmButtonColor: \'#6366f1\', customClass: { popup: \'text-sm\' }});\n                return;\n            }\n            \n            Swal.fire({\n                title: \'Confirm\',\n                html: `Approve <b class="text-white">${item[1]}</b> for <span class="text-emerald-400 font-bold">₹${formatInr(item[6])}</span>?`,\n                icon: \'question\',\n                showCancelButton: true,\n                background: \'#1e293b\',\n                color: \'#fff\',\n                confirmButtonColor: \'#10b981\',\n                cancelButtonColor: \'#475569\',\n                confirmButtonText: \'Approve\',\n                customClass: { popup: \'text-sm\' }\n            }).then(async (result) => {\n                if (result.isConfirmed) {\n                    try {\n                        const res = await fetch(\'/api/approve\', {\n                            method: \'POST\',\n                            headers: {\'Content-Type\': \'application/json\'},\n                            body: JSON.stringify({ vcodes: [item[0]] })\n                        });\n                        const data = await res.json();\n                        if(data.success) {\n                            Toast.fire({icon: \'success\', title: `Approved ${item[1]}`});\n                            fetchData();\n                        } else throw new Error(data.error);\n                    } catch (e) {\n                        Swal.fire({icon: \'error\', title: \'Error\', text: e.message, background: \'#1e293b\', color: \'#fff\'});\n                    }\n                }\n            });\n        }\n\n        function approveAll() {\n            if(isLocked) return;\n            Swal.fire({\n                title: \'Approve All?\',\n                text: `Approve ${pendingData.length} vouchers?`,\n                icon: \'warning\',\n                showCancelButton: true,\n                background: \'#1e293b\',\n                color: \'#fff\',\n                confirmButtonColor: \'#10b981\',\n                cancelButtonColor: \'#475569\',\n                confirmButtonText: \'Approve All\',\n                customClass: { popup: \'text-sm\' }\n            }).then(async (result) => {\n                if (result.isConfirmed) {\n                    try {\n                        const vcodes = pendingData.map(i => i[0]);\n                        const res = await fetch(\'/api/approve\', {\n                            method: \'POST\',\n                            headers: {\'Content-Type\': \'application/json\'},\n                            body: JSON.stringify({ vcodes: vcodes })\n                        });\n                        const data = await res.json();\n                        if(data.success) {\n                            Toast.fire({icon: \'success\', title: `Approved ${vcodes.length} vouchers!`});\n                            fetchData();\n                        } else throw new Error(data.error);\n                    } catch (e) {\n                        Swal.fire({icon: \'error\', title: \'Error\', text: e.message, background: \'#1e293b\', color: \'#fff\'});\n                    }\n                }\n            });\n        }\n\n        function cancelApproval() {\n            if(isLocked) return;\n            Swal.fire({\n                title: \'Cancel Approval?\',\n                text: `Cancel ${selectedApproved.size} vouchers?`,\n                icon: \'warning\',\n                showCancelButton: true,\n                background: \'#1e293b\',\n                color: \'#fff\',\n                confirmButtonColor: \'#ef4444\',\n                cancelButtonColor: \'#475569\',\n                confirmButtonText: \'Cancel Apprv\',\n                customClass: { popup: \'text-sm\' }\n            }).then(async (result) => {\n                if (result.isConfirmed) {\n                    try {\n                        const vcodes = Array.from(selectedApproved);\n                        const res = await fetch(\'/api/cancel\', {\n                            method: \'POST\',\n                            headers: {\'Content-Type\': \'application/json\'},\n                            body: JSON.stringify({ vcodes: vcodes })\n                        });\n                        const data = await res.json();\n                        if(data.success) {\n                            Toast.fire({icon: \'success\', title: `Cancelled ${vcodes.length} vouchers.`});\n                            selectedApproved.clear();\n                            document.getElementById(\'selectAll\').checked = false;\n                            fetchData();\n                        } else throw new Error(data.error);\n                    } catch (e) {\n                        Swal.fire({icon: \'error\', title: \'Error\', text: e.message, background: \'#1e293b\', color: \'#fff\'});\n                    }\n                }\n            });\n        }\n\n        // Subtler fade-in for compact UI\n        const style = document.createElement(\'style\');\n        style.innerHTML = `\n            @keyframes fadeIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }\n            .fade-in { animation: fadeIn 0.3s ease-out forwards; opacity: 0; }\n        `;\n        document.head.appendChild(style);\n\n        // Toast configuration\n        const Toast = Swal.mixin({\n            toast: true,\n            position: \'bottom-end\',\n            showConfirmButton: false,\n            timer: 2000,\n            timerProgressBar: true,\n            background: \'#1e293b\',\n            color: \'#fff\',\n            customClass: { popup: \'text-xs\' },\n            didOpen: (toast) => {\n                toast.addEventListener(\'mouseenter\', Swal.stopTimer)\n                toast.addEventListener(\'mouseleave\', Swal.resumeTimer)\n            }\n        });\n\n        function copyClientLink() {\n            const el = document.getElementById(\'client-ip-display\');\n            if(!el) return;\n            const url = el.innerText.trim();\n            if (navigator.clipboard && window.isSecureContext) {\n                navigator.clipboard.writeText(url).then(() => {\n                    Toast.fire({icon: \'info\', title: \'Client link copied!\'});\n                }).catch(() => {\n                    prompt("Client Computer Link (Copy with Ctrl+C):", url);\n                });\n            } else {\n                prompt("Client Computer Link (Copy with Ctrl+C):", url);\n            }\n        }\n    </script>\n</body>\n</html>\n'
